/* =====================================================================
   Procedural audio — Web Audio only, created on first user gesture.
   ===================================================================== */
const audio = {
  ctx: null, master: null, muted: false, noiseBuf: null,
  ensure(){
    if (this.ctx) return true;
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return false;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.5;
      this.master.connect(this.ctx.destination);
      const len = this.ctx.sampleRate * 2;
      this.noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const d = this.noiseBuf.getChannelData(0);
      let last = 0;
      for (let i = 0; i < len; i++){ const w = Math.random() * 2 - 1; last = (last + 0.02 * w) / 1.02; d[i] = last * 3.2; }
      const wind = this.ctx.createBufferSource();
      wind.buffer = this.noiseBuf; wind.loop = true;
      const wf = this.ctx.createBiquadFilter(); wf.type = 'lowpass'; wf.frequency.value = 320;
      const wg = this.ctx.createGain(); wg.gain.value = 0.035;
      wind.connect(wf); wf.connect(wg); wg.connect(this.master);
      wind.start();
    } catch (e){ this.ctx = null; return false; }
    return true;
  },
  resume(){ if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(()=>{}); },
  out(){ return this.master; },
  tone(o){
    if (!this.ctx || this.muted) return;
    const c = this.ctx, t0 = c.currentTime + (o.delay || 0);
    const osc = c.createOscillator(), gn = c.createGain();
    osc.type = o.type || 'sine';
    osc.frequency.setValueAtTime(o.f, t0);
    if (o.f2) osc.frequency.exponentialRampToValueAtTime(Math.max(1, o.f2), t0 + o.dur);
    gn.gain.setValueAtTime(0.0001, t0);
    gn.gain.linearRampToValueAtTime(o.g, t0 + (o.a || 0.004));
    gn.gain.exponentialRampToValueAtTime(0.0001, t0 + o.dur);
    osc.connect(gn); gn.connect(this.out());
    osc.start(t0); osc.stop(t0 + o.dur + 0.05);
  },
  noise(o){
    if (!this.ctx || this.muted) return;
    const c = this.ctx, t0 = c.currentTime + (o.delay || 0);
    const src = c.createBufferSource(); src.buffer = this.noiseBuf;
    src.playbackRate.value = o.rate || 1;
    const f = c.createBiquadFilter();
    f.type = o.ftype || 'bandpass'; f.frequency.setValueAtTime(o.f || 1000, t0); f.Q.value = o.q || 1;
    if (o.f2) f.frequency.exponentialRampToValueAtTime(Math.max(10, o.f2), t0 + o.dur);
    const gn = c.createGain();
    gn.gain.setValueAtTime(0.0001, t0);
    gn.gain.linearRampToValueAtTime(o.g, t0 + (o.a || 0.005));
    gn.gain.exponentialRampToValueAtTime(0.0001, t0 + o.dur);
    src.connect(f); f.connect(gn); gn.connect(this.out());
    src.start(t0, Math.random() * 1.2); src.stop(t0 + o.dur + 0.05);
  },
  play(name, ev){
    if (!this.ctx || this.muted) return;
    switch (name){
      case 'swing':  this.noise({ f:900, f2:340, dur:0.12, g:0.05, q:1.6 }); break;
      case 'parry':
        this.tone({ type:'square', f: ev && ev.perfect ? 1560 : 1320, dur:0.16, g:0.055 });
        this.tone({ type:'sine', f:2093, dur:0.22, g:0.04 });
        this.noise({ f:5200, dur:0.05, g:0.07, ftype:'highpass' });
        if (ev && ev.perfect) this.tone({ type:'sine', f:2637, dur:0.4, g:0.035, delay:0.02 });
        break;
      case 'deflect':
        this.tone({ type:'square', f:1180, dur:0.12, g:0.045 });
        this.noise({ f:3600, dur:0.07, g:0.05, ftype:'highpass' });
        break;
      case 'featherHit':
        this.noise({ f:700, f2:220, dur:0.14, g:0.06 });
        this.tone({ type:'sine', f:330, f2:180, dur:0.12, g:0.05 });
        break;
      case 'riposte':
        this.noise({ f:400, f2:2400, dur:0.2, g:0.09, q:2 });
        this.tone({ type:'square', f:1560, dur:0.18, g:0.05, delay:0.03 });
        this.tone({ type:'sine', f:82, f2:44, dur:0.5, g:0.12, delay:0.03 });
        break;
