  el.endSub.textContent = win ? 'Sumi dissolves into the paper' : 'Sumi looms, unbroken';
  const s = S.stats;
  const denom = s.parries + s.whiffs + s.hits;
  const acc = denom ? Math.round(s.parries / denom * 100) : 100;
  el.stats.innerHTML = '';
  [['time', (S.t / 1000).toFixed(1) + 's'], ['parries', s.parries], ['perfect', s.perfects],
   ['hits taken', s.hits], ['best combo', s.bestCombo], ['accuracy', acc + '%']]
    .forEach(([k, v]) => {
      const d = document.createElement('div');
      const b = document.createElement('b');
      b.textContent = String(v);
      d.append(k, b);
      el.stats.appendChild(d);
    });
  let rank = 'C';
  if (win){ rank = s.hits === 0 && s.whiffs <= 2 ? 'S' : s.hits <= 1 ? 'A' : 'B'; }
  el.rank.textContent = win ? 'rank ' + rank : '';
  announce(win ? 'Victory. The ink settles.' : 'Defeat. The lantern goes out.');
}

/* ---------- event drain ---------- */
function drainEvents(){
  const evs = game.sim.events;
  if (!evs.length) return;
  for (const ev of evs){
    onEvent(ev, game.sim);
    const snd = SOUND_MAP[ev.type];
    if (snd) audio.play(snd, ev);
    if (ev.type === 'fightstart') caption('Strike when the ring flashes.', 2600);
    else if (ev.type === 'phasebegin'){
      if (ev.phase === 2){ caption('II — The Feather Storm · struck feathers fly back', 3400); announce('Phase two: the feather storm.'); }
      if (ev.phase === 3){ caption('III — The Eclipse · answer every beat of the dive', 3400); announce('Phase three: the eclipse.'); }
    }
  }
  evs.length = 0;
}

/* ---------- input ---------- */
el.stage.addEventListener('pointerdown', e => { e.preventDefault(); userPress(); });
el.stage.addEventListener('contextmenu', e => e.preventDefault());
window.addEventListener('keydown', e => {
  const onButton = document.activeElement && document.activeElement.tagName === 'BUTTON';
  if (e.code === 'Space'){
    if (onButton) return;               // let Space activate a focused control
    e.preventDefault();
    if (!e.repeat) userPress();
    return;
  }
  if (e.repeat) return;
  if (e.code === 'KeyP' || e.code === 'Escape') togglePause();
  else if (e.code === 'KeyR'){ cancelAttract(); game.interacted = true; restart(); }
  else if (e.code === 'KeyD') toggleDemo();
  else if (e.code === 'KeyM') toggleSound();
});

function togglePause(){
  if (!game.clock && game.sim.t === 0) return;
  game.autoPaused = false;
  setPaused(!game.paused);
  if (!game.paused){ audio.ensure(); audio.resume(); }
}
function toggleDemo(){
  cancelAttract(); game.interacted = true;
  if (!game.sim.demo) enterDemo();
  else game.sim.setDemo(false);
}
function toggleSound(){
  audio.ensure(); audio.resume();
  audio.muted = !audio.muted;
  el.btnSound.setAttribute('aria-pressed', String(!audio.muted));
  el.btnSound.textContent = audio.muted ? 'Sound: Off' : 'Sound: On';
}
function bindButton(btn, fn){
  btn.addEventListener('click', e => {
    fn();
    if (e.detail > 0) el.stage.focus();   // mouse click: hand focus back to the arena
  });
}
bindButton(el.btnStart, () => {
  cancelAttract(); game.interacted = true;
  audio.ensure(); audio.resume();
  const s = game.sim;
  if (game.paused){ setPaused(false); return; }
  if (s.outcome || s.demo || !game.clock) startFresh();
});
bindButton(el.btnPause, togglePause);
bindButton(el.btnRestart, () => { cancelAttract(); game.interacted = true; audio.ensure(); audio.resume(); restart(); });
bindButton(el.btnDemo, toggleDemo);
bindButton(el.btnSound, toggleSound);
el.btnSound.textContent = 'Sound: On';
el.btnSound.setAttribute('aria-pressed', 'true');

/* ---------- lifecycle ---------- */
window.addEventListener('resize', resize);
document.addEventListener('visibilitychange', () => {
  if (document.hidden){
    if (game.clock && !game.paused){ setPaused(true); game.autoPaused = true; }
  } else if (game.autoPaused){
    game.autoPaused = false;
    if (game.sim.demo) setPaused(false);   // attract resumes; real play stays safely paused
  }
});

/* ---------- main loop ---------- */
let last = performance.now();
function frame(now){
  const dt = Math.min(100, Math.max(0, now - last));
  last = now;
  if (game.clock && !game.paused && !document.hidden) game.sim.step(dt);
  drainEvents();
  draw(game.sim, now, dt || 16);
  updateHud(game.sim);
  requestAnimationFrame(frame);
}

/* ---------- deterministic public interface ---------- */
window.__BOSS_FIGHT__ = {
  reset(seed){
    cancelAttract();
    game.sim.reset(seed === undefined ? game.sim.seed : seed);
    game.sim.demo = false;
    game.clock = false; setPaused(false);
    return game.sim.snapshot();
  },
  start(){
    cancelAttract();
    if (game.sim.outcome) game.sim.reset(game.sim.seed);
    game.sim.demo = false;
    game.clock = true; setPaused(false);
    return true;
  },
  setDemo(enabled){
    cancelAttract();
    game.sim.setDemo(!!enabled);
    if (enabled){ game.clock = true; setPaused(false); }
    return game.sim.demo;
  },
  press(){ cancelAttract(); game.sim.press(); return true; },
  step(ms){ cancelAttract(); game.sim.step(+ms || 0); return r3(game.sim.t); },
  snapshot(){ return game.sim.snapshot(); },
  runSelfTest(){ return runSelfTest(); },
};

/* ---------- boot ---------- */
resize();
el.stage.focus();
game.attractTimer = setTimeout(() => {
  game.attractTimer = 0;
  if (!game.interacted && !game.clock && game.sim.t === 0) enterDemo();
}, 7000);
requestAnimationFrame(frame);

})();

